commands:
if (-NOT ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) {exit}

$canDisableOffloads = $true
$rssValue = "0"
$offloadValue = "0"
$checksumValue = "0"

$cpuDetected = $false
try {
    $cpu = Get-CimInstance Win32_Processor -ErrorAction Stop
    if ($cpu) {
        $physicalCores = $cpu.NumberOfCores
        $cpuName = $cpu.Name
        $maxClockSpeed = $cpu.MaxClockSpeed
        $cpuDetected = $true
    }
} catch {}

if (-not $cpuDetected) {
    try {
        $cpu = Get-WmiObject Win32_Processor -ErrorAction Stop
        $physicalCores = $cpu.NumberOfCores
        $cpuName = $cpu.Name
        $maxClockSpeed = $cpu.MaxClockSpeed
        $cpuDetected = $true
    } catch {}
}

if ($cpuDetected) {
    $canDisableOffloads = $true
    $rssValue = "0"
}

$offloadValue = "0"
$checksumValue = "0"

$adapterKeyPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4D36E972-E325-11CE-BFC1-08002BE10318}"
$allAdapters = Get-ChildItem $adapterKeyPath -ErrorAction SilentlyContinue

$ethAdapters = $allAdapters | Where-Object { (Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue).DriverDesc -match "Ethernet|LAN|GbE|Realtek|Intel|Killer|Broadcom|Qualcomm|BCM" }

foreach ($adapter in $ethAdapters) {
    $path = $adapter.PSPath
    "EEE","*EEE","GreenEthernet","PowerSavingMode","AutoDisableGigabit","AdvancedEEE","EnableGreenEthernet","NicAutoPowerSaver","*WakeOnMagicPacket","*WakeOnPattern" | ForEach-Object { New-ItemProperty -Path $path -Name $_ -Value "0" -PropertyType String -Force -ErrorAction SilentlyContinue | Out-Null }
    New-ItemProperty -Path $path -Name "*InterruptModeration" -Value "0" -PropertyType String -Force -ErrorAction SilentlyContinue | Out-Null
    New-ItemProperty -Path $path -Name "InterruptModeration" -Value 0 -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
    New-ItemProperty -Path $path -Name "RxIntModeration" -Value 0 -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
    New-ItemProperty -Path $path -Name "TxIntModeration" -Value 0 -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
    New-ItemProperty -Path $path -Name "*FlowControl" -Value "0" -PropertyType String -Force -ErrorAction SilentlyContinue | Out-Null
    New-ItemProperty -Path $path -Name "FlowControl" -Value 0 -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
    New-ItemProperty -Path $path -Name "*JumboPacket" -Value "1514" -PropertyType String -Force -ErrorAction SilentlyContinue | Out-Null
    New-ItemProperty -Path $path -Name "JumboPacket" -Value 1514 -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
    New-ItemProperty -Path $path -Name "*RSS" -Value $rssValue -PropertyType String -Force -ErrorAction SilentlyContinue | Out-Null
    New-ItemProperty -Path $path -Name "*NumRssQueues" -Value "1" -PropertyType String -Force -ErrorAction SilentlyContinue | Out-Null
    New-ItemProperty -Path $path -Name "RSS" -Value 0 -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
    "*LsoV1IPv4","*LsoV2IPv4","*LsoV2IPv6","*RscIPv4","*RscIPv6" | ForEach-Object { New-ItemProperty -Path $path -Name $_ -Value "0" -PropertyType String -Force -ErrorAction SilentlyContinue | Out-Null }
    "*IPChecksumOffloadIPv4","*TCPChecksumOffloadIPv4","*UDPChecksumOffloadIPv4","*TCPChecksumOffloadIPv6","*UDPChecksumOffloadIPv6" | ForEach-Object { New-ItemProperty -Path $path -Name $_ -Value "0" -PropertyType String -Force -ErrorAction SilentlyContinue | Out-Null }
    New-ItemProperty -Path $path -Name "*ReceiveBuffers" -Value "512" -PropertyType String -Force -ErrorAction SilentlyContinue | Out-Null
    New-ItemProperty -Path $path -Name "*TransmitBuffers" -Value "1024" -PropertyType String -Force -ErrorAction SilentlyContinue | Out-Null
    New-ItemProperty -Path $path -Name "RecvCompletionMethod" -Value 0 -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
    New-ItemProperty -Path $path -Name "NdisPoll" -Value 1 -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
    New-ItemProperty -Path $path -Name "ThreadPoll" -Value 3000 -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
}

$wifiAdapters = $allAdapters | Where-Object { (Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue).DriverDesc -match "Wi-Fi|Wireless|Realtek|Intel|Killer|Broadcom|Qualcomm|Atheros|BCM" }

foreach ($adapter in $wifiAdapters) {
    $path = $adapter.PSPath
    "PowerSavingMode","UAPSD","*UAPSD","*WakeOnMagicPacket","*WakeOnPattern","PacketCoalescing","*PacketCoalescing" | ForEach-Object { New-ItemProperty -Path $path -Name $_ -Value "0" -PropertyType String -Force -ErrorAction SilentlyContinue | Out-Null }
    New-ItemProperty -Path $path -Name "*TransmitPower" -Value "100" -PropertyType String -Force -ErrorAction SilentlyContinue | Out-Null
    New-ItemProperty -Path $path -Name "TransmitPower" -Value 100 -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
    New-ItemProperty -Path $path -Name "RoamingAggressiveness" -Value 1 -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
    "*PMARPOffload","*PMNSOffload" | ForEach-Object { New-ItemProperty -Path $path -Name $_ -Value "0" -PropertyType String -Force -ErrorAction SilentlyContinue | Out-Null }
}

try {
    $i219Adapters = $allAdapters | Where-Object { (Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue).DriverDesc -match "I218|I219" }
    foreach ($adapter in $i219Adapters) {
        $path = $adapter.PSPath
        New-ItemProperty -Path $path -Name "I219DisableK1Off" -Value 1 -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
        New-ItemProperty -Path $path -Name "EnableD3ColdInS0" -Value 0 -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
        New-ItemProperty -Path $path -Name "I218DisablePLLShut" -Value 1 -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
        New-ItemProperty -Path $path -Name "I218DisablePLLShutGiga" -Value 1 -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
    }
} catch {}

